{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/logo-cloud.json
    A heading and the names of customers or partners as Lucide glyphs with a name. Axes: layout (grid, row), columns (2, 3, 4), item (name, icon only, tile), density, tone.
    Props (p): id, title, logos, empty, layout, cols, item, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_logos = ($p['logos'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_cols = ($p['cols'] ?? '4')}
{var $v_item = ($p['item'] ?? 'name')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{if og_t(og_eq(og_len($v_logos), 0))}
  {capture $c_1}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'building-2', 'title' => $v_empty]])|noescape}
  {/capture}
  {=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'align' => 'center', 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_1)])|noescape}
{elseif og_t(og_eq($v_layout, 'row'))}
  {=og_include('blocks/logo-ribbon.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'logos' => $v_logos, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel]])|noescape}
{else}
  {capture $c_5}
    {capture $c_4}
      {foreach og_l($v_logos) as $v_logo}
        {capture $c_3}
          {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_logo, ['icon'])), 'size' => 24])|noescape}
          {capture $c_2}
            {=og_text(og_get($v_logo, ['name']))}
          {/capture}
          {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'class' => og_s((og_t(og_eq($v_item, 'icon')) ? 'sr-only' : '')), 'children' => (string) $c_2])|noescape}
        {/capture}
        {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'justify' => 'center', 'class' => og_s(og_cnv(['text-muted-foreground', (og_t(og_eq($v_item, 'tile')) ? 'flex-col rounded p-4 inset-ring inset-ring-border' : '')])), 'attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_3])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => og_s((og_t(og_eq($v_cols, '2')) ? '2' : (og_t(og_eq($v_cols, '3')) ? '2-3' : (og_t(og_eq($v_cols, '4')) ? '2-4' : '3-6')))), 'class' => 'gap-4', 'attrs' => og_attrs(['data-testid', 'items']), 'children' => (string) $c_4])|noescape}
  {/capture}
  {=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'align' => 'center', 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_5)])|noescape}
{/if}
